import React, { useState } from 'react';
import { 
  Home, List, BookOpen, Database, Menu, X, ChevronLeft, ArrowRight, Triangle, ArrowUp, ArrowDown 
} from 'lucide-react';
import {
  XAxis, YAxis, CartesianGrid, ResponsiveContainer, LineChart, Line, AreaChart, Area
} from 'recharts';

// --- 型定義 ---
interface RankingItem {
  rank: number;
  title: string;
  isbn: string;
}

// --- モックデータ (JSONファイルを想定) ---
const jsonData = {
  issue: "2026年 第10号",
  rankings: [
    { rank: 1, title: "ONE PIECE", isbn: "978-4-08-884013-0" },
    { rank: 2, title: "呪術廻戦", isbn: "978-4-08-883595-2" },
    { rank: 3, title: "僕のヒーローアカデミア", isbn: "978-4-08-883842-7" },
    { rank: 4, title: "サカモトデイズ", isbn: "978-4-08-884013-0" },
    { rank: 5, title: "アオのハコ", isbn: "978-4-08-883000-0" },
    { rank: 6, title: "夜桜さんちの大作戦", isbn: "978-4-08-883000-1" },
    { rank: 7, title: "アンデッドアンラック", isbn: "978-4-08-883000-2" },
    { rank: 8, title: "新連載", isbn: "978-4-08-883000-3" }
  ]
};

const trendData = [
  { name: '第6号', op: 1.2, jjk: 2.1, mha: 2.8 },
  { name: '第7号', op: 1.8, jjk: 1.5, mha: 3.0 },
  { name: '第8号', op: 1.1, jjk: 2.3, mha: 1.5 },
  { name: '第9号', op: 1.5, jjk: 2.0, mha: 2.2 },
  { name: '第10号', op: 1.0, jjk: 1.8, mha: 2.5 },
];

export default function IssueRanking() {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'all'>('home');

  const colors = {
    bg: '#0f172a',
    sidebar: '#1a2235',
    card: '#161d2f',
    accent: '#3b82f6',
    border: '#2d3748',
    textMuted: '#94a3b8'
  };

  // 共通レイアウトスタイル
  const sidebarStyle: React.CSSProperties = {
    width: '240px',
    backgroundColor: colors.sidebar,
    position: 'fixed',
    height: '100vh',
    left: isSidebarOpen ? '0' : '-240px',
    transition: 'left 0.3s ease',
    zIndex: 90,
    paddingTop: '80px',
    borderRight: `1px solid ${colors.border}`,
    boxShadow: isSidebarOpen ? '10px 0 30px rgba(0,0,0,0.5)' : 'none'
  };

  return (
    <div style={{ display: 'flex', backgroundColor: colors.bg, minHeight: '100vh', color: 'white', fontFamily: 'sans-serif' }}>

      {/* ハンバーガーメニュー */}
      <button 
        onClick={() => setSidebarOpen(!isSidebarOpen)} 
        style={{ position: 'fixed', top: '20px', left: '20px', zIndex: 100, backgroundColor: colors.sidebar, border: `1px solid ${colors.border}`, borderRadius: '4px', padding: '8px', cursor: 'pointer', color: 'white' }}
      >
        {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
      </button>

      {/* サイドバー */}
      <aside style={sidebarStyle}>
        <div style={{ padding: '0 24px', marginBottom: '30px', fontSize: '18px', fontWeight: 'bold' }}>ジャンプ順位管理</div>
        <nav>
          {[
            { icon: <Home size={18}/>, label: "ホーム", mode: 'home' },
            { icon: <List size={18}/>, label: "号別ランキング", mode: 'all' },
            { icon: <BookOpen size={18}/>, label: "作品一覧", mode: 'all' },
            { icon: <Database size={18}/>, label: "データ管理", mode: 'home' }
          ].map((item, i) => (
            <div 
              key={i} 
              onClick={() => { setViewMode(item.mode as any); setSidebarOpen(false); }}
              style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '15px 24px', cursor: 'pointer', color: (viewMode === item.mode && i < 2) ? colors.accent : 'white', backgroundColor: (viewMode === item.mode && i < 2) ? 'rgba(59, 130, 246, 0.1)' : 'transparent' }}
            >
              {item.icon} <span style={{ fontSize: '14px' }}>{item.label}</span>
            </div>
          ))}
        </nav>
      </aside>

      {/* メインエリア */}
      <main style={{ flex: 1, padding: '80px 20px', maxWidth: '800px', margin: '0 auto' }}>

        {viewMode === 'home' ? (
          /* --- ホーム画面 --- */
          <>
            <h2 style={{ fontSize: '24px', fontWeight: 'bold', borderBottom: `2px solid ${colors.accent}`, display: 'inline-block', marginBottom: '30px', paddingBottom: '4px' }}>
              {jsonData.issue}
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginBottom: '30px' }}>
              {jsonData.rankings.slice(0, 5).map((item) => (
                <div key={item.rank} style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <span style={{ fontSize: '20px', fontWeight: 'bold', fontStyle: 'italic', width: '40px' }}>{item.rank}位</span>
                  <span style={{ fontSize: '18px' }}>{item.title}</span>
                </div>
              ))}
            </div>

            <button 
              onClick={() => setViewMode('all')}
              style={{ width: '100%', padding: '14px', backgroundColor: '#252f48', border: `1px solid ${colors.border}`, borderRadius: '8px', color: 'white', cursor: 'pointer', fontWeight: 'bold', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px' }}
            >
              全順位を見る <ArrowRight size={16} />
            </button>

            <div style={{ marginTop: '50px' }}>
              <h3 style={{ fontSize: '14px', color: colors.textMuted, borderBottom: `1px solid ${colors.border}`, paddingBottom: '8px', marginBottom: '20px' }}>トレンド推移</h3>
              <div style={{ height: '200px', backgroundColor: colors.card, padding: '20px', borderRadius: '12px', border: `1px solid ${colors.border}` }}>
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={trendData}>
                    <CartesianGrid vertical={false} stroke={colors.border} strokeDasharray="3 3" />
                    <XAxis dataKey="name" tick={{fill: colors.textMuted, fontSize: 11}} axisLine={false} tickLine={false} />
                    <YAxis reversed domain={[1, 4]} hide />
                    <Line type="monotone" dataKey="op" stroke="#60a5fa" strokeWidth={3} dot={{r: 4, fill: '#fff'}} />
                    <Line type="monotone" dataKey="jjk" stroke="#f87171" strokeWidth={2} dot={{r: 3}} />
                    <Line type="monotone" dataKey="mha" stroke="#4ade80" strokeWidth={2} dot={{r: 3}} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>
          </>
        ) : (
          /* --- 全順位テーブル画面 --- */
          <>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '30px' }}>
              <button onClick={() => setViewMode('home')} style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer' }}><ChevronLeft size={28} /></button>
              <h2 style={{ fontSize: '24px', fontWeight: 'bold' }}>{jsonData.issue} ランキング</h2>
            </div>

            <div style={{ backgroundColor: colors.card, borderRadius: '12px', border: `1px solid ${colors.border}`, overflow: 'hidden' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ textAlign: 'left', borderBottom: `1px solid ${colors.border}`, color: colors.textMuted, fontSize: '13px' }}>
                    <th style={{ padding: '15px 20px' }}>順位</th>
                    <th style={{ padding: '15px 20px' }}>作品名</th>
                    <th style={{ padding: '15px 20px' }}>詳細リンク</th>
                  </tr>
                </thead>
                <tbody>
                  {jsonData.rankings.map((item) => (
                    <tr key={item.rank} style={{ borderBottom: `1px solid ${colors.border}` }}>
                      <td style={{ padding: '15px 20px', fontSize: '18px', fontWeight: 'bold', fontStyle: 'italic' }}>{item.rank}位</td>
                      <td style={{ padding: '15px 20px', fontSize: '16px' }}>{item.title}</td>
                      <td style={{ padding: '15px 20px' }}>
                        <a 
                          href={`https://www.shueisha.co.jp/books/items/contents.html?isbn=${item.isbn}`} 
                          target="_blank" rel="noopener noreferrer"
                          style={{ color: colors.accent, textDecoration: 'none', fontSize: '13px', fontWeight: 'bold' }}
                        >
                          公式サイト ↗
                        </a>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </main>

      {/* オーバーレイ */}
      {isSidebarOpen && (
        <div onClick={() => setSidebarOpen(false)} style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.6)', zIndex: 80 }} />
      )}
    </div>
  );
}
